const CallerRow: React.FC<{
  row: typeof CALL_DATA[0];
  index: number;
  totalRows: number;
  staggerFrames: number;
  themeColor: string;
  dangerColor: string;
  textColor: string;
  subTextColor: string;
}> = ({ row, index, totalRows, staggerFrames, themeColor, dangerColor, textColor, subTextColor }) => {
  const frame = useCurrentFrame();
  
  // Stagger from bottom (highest index) to top (index 0)
  const popDelay = (totalRows - 1 - index) * staggerFrames + 30; 
  
  const popProgress = interpolate(frame - popDelay, [0, 6, 14], [0, 1, 2], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp'
  });

  let scale = 1;
  let opacity = 1;
  
  if (popProgress > 0 && popProgress <= 1) {
    // Inflate pop
    scale = interpolate(popProgress, [0, 1], [1, 1.15], { easing: Easing.out(Easing.quad) });
  } else if (popProgress > 1) {
    // Shrink and disappear
    scale = interpolate(popProgress, [1, 2], [1.15, 0], { easing: Easing.in(Easing.quad) });
    opacity = interpolate(popProgress, [1, 1.5], [1, 0], { extrapolateRight: 'clamp' });
  }

  return (
    <div style={{
      transform: `scale(${scale})`,
      opacity: opacity,
      display: 'flex',
      height: 64,
      alignItems: 'center',
      paddingLeft: 20,
      transformOrigin: 'center center',
      willChange: 'transform, opacity',
      transition: 'none',
    }}>
      {/* Avatar */}
      <div style={{ width: 44, height: 44, borderRadius: 22, backgroundColor: '#C6DDE7', display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: 26, overflow: 'hidden', flexShrink: 0 }}>
        <div style={{ transform: 'translateY(4px)' }}>🧔‍♂️</div>
      </div>
      
      {/* Content */}
      <div style={{ flex: 1, borderBottom: '1px solid #38383A', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginLeft: 12, paddingRight: 20 }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
           <div style={{ fontSize: 18, fontWeight: 600, color: row.isMissed ? dangerColor : textColor, letterSpacing: '-0.3px' }}>
             {row.name}
           </div>
           <div style={{ fontSize: 14, color: subTextColor, display: 'flex', alignItems: 'center', gap: 4 }}>
              {!row.isMissed && <CallIcon type={row.type} />}
              <span>{row.type}</span>
           </div>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
           <div style={{ fontSize: 15, color: subTextColor }}>{row.date}</div>
           <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke={themeColor} strokeWidth="1.5">
             <circle cx="12" cy="12" r="10" />
             <path d="M12 16v-4" strokeLinecap="round" />
             <path d="M12 8h.01" strokeWidth="2" strokeLinecap="round" />
           </svg>
        </div>
      </div>
    </div>
  );
};

